/* global describe, it, expect, vi, afterEach -- vitest globals (globals: true); declared for `eslint .` */
/**
 * Characterization tests for src/pages/editor/utils/codeExporter.ts.
 *
 * They pin the CURRENT generated output byte-for-byte so the module can be split up later without
 * changing what users export. codeExporter.golden.json was captured once from the unmodified module
 * (same fixtures, fixed clock for the countdown default) and is never regenerated by this test.
 * If an intentional output change is made, re-capture the golden file deliberately and review the diff.
 *
 * Determinism: the only clock-dependent path (countdown without a target date defaults to now + 7 days)
 * runs under fake timers at FIXED_NOW. Output was verified identical across runs and time zones.
 *
 * Runs with vitest globals (describe/it/expect/vi) and no frontend dependencies:
 *   cd backend && npx vitest run --config ../frontend/vitest.characterization.config.mjs
 */
import { readFileSync } from "node:fs";
import {
  exportCode,
  exportEntireWebsite,
  formatStylesToCSS,
  formatStylesToJSX,
  generateJSCode,
  generateJSXCode,
  generateTSCode,
  generateTSXCode,
  toPascalCase,
} from "../../src/pages/editor/utils/codeExporter";
import { CLOCK_CASES, ELEMENT_CASES, FIXED_NOW, FORMATS, HELPER_CASES, WEBSITE } from "./codeExporter.fixtures";

const golden: Record<string, any> = JSON.parse(readFileSync(new URL("./codeExporter.golden.json", import.meta.url), "utf8"));

const GENERATORS: Record<(typeof FORMATS)[number], (el: any) => string> = {
  jsx: generateJSXCode,
  tsx: generateTSXCode,
  js: generateJSCode,
  ts: generateTSCode,
};

const elementKeys = Object.keys(ELEMENT_CASES).flatMap((n) => FORMATS.map((f) => `element:${n}:${f}`));
const clockKeys = Object.keys(CLOCK_CASES).flatMap((n) => FORMATS.map((f) => `clock:${n}:${f}`));

describe("codeExporter golden file", () => {
  it("covers exactly the fixture cases (no missing or stale entries)", () => {
    const expected = [...elementKeys, ...clockKeys, "website", "helper:toPascalCase", "helper:formatStylesToCSS",
      "helper:formatStylesToJSX", "empty:jsx"].sort();
    expect(Object.keys(golden).sort()).toEqual(expected);
  });
});

describe("element export: byte-for-byte against golden output", () => {
  for (const [name, el] of Object.entries(ELEMENT_CASES)) {
    for (const format of FORMATS) {
      it(`${name} as ${format}`, () => {
        const before = JSON.stringify(el);
        const out = exportCode(el, format);
        expect(out).toBe(golden[`element:${name}:${format}`]);
        // exportCode dispatches to the per-format generator unchanged.
        expect(GENERATORS[format](el)).toBe(out);
        // Generation is pure: same output again, and the input element is not mutated.
        expect(exportCode(el, format)).toBe(out);
        expect(JSON.stringify(el)).toBe(before);
      });
    }
  }

  it("exportCode defaults to JSX", () => {
    expect(exportCode(ELEMENT_CASES.container)).toBe(golden["element:container:jsx"]);
  });

  it("no element selected", () => {
    expect(generateJSXCode(undefined as any)).toBe(golden["empty:jsx"]);
  });
});

describe("clock-dependent defaults under a fixed clock", () => {
  afterEach(() => vi.useRealTimers());

  for (const [name, el] of Object.entries(CLOCK_CASES)) {
    for (const format of FORMATS) {
      it(`${name} as ${format}`, () => {
        vi.useFakeTimers({ now: new Date(FIXED_NOW) });
        expect(exportCode(el, format)).toBe(golden[`clock:${name}:${format}`]);
      });
    }
  }
});

describe("exportEntireWebsite: byte-for-byte project files", () => {
  it("produces the same files, in the same order, with identical contents", () => {
    const before = JSON.stringify(WEBSITE);
    const files = exportEntireWebsite(WEBSITE);
    expect(Object.keys(files)).toEqual(Object.keys(golden.website));
    for (const [file, content] of Object.entries(golden.website)) {
      expect(files[file], file).toBe(content);
    }
    expect(JSON.stringify(WEBSITE)).toBe(before);
  });

  it("is deterministic across calls", () => {
    expect(exportEntireWebsite(WEBSITE)).toEqual(exportEntireWebsite(WEBSITE));
  });
});

describe("pure helpers", () => {
  it("toPascalCase", () => {
    expect(HELPER_CASES.toPascalCase.map((s) => toPascalCase(s))).toEqual(golden["helper:toPascalCase"]);
  });

  it("formatStylesToCSS / formatStylesToJSX", () => {
    expect(formatStylesToCSS(HELPER_CASES.styles)).toBe(golden["helper:formatStylesToCSS"]);
    expect(formatStylesToJSX(HELPER_CASES.styles)).toBe(golden["helper:formatStylesToJSX"]);
  });
});
